// qrcodejs-compatible — Re-fill project — MIT
// I rewrote this from the davidshimjs/qrcodejs source because the bundled copy
// had a corrupted syntax error. RS_BLOCK_TABLE values verified against ISO 18004:2006.
(function(){
"use strict";

// ── GF(256) tables for Reed-Solomon, primitive poly x^8+x^4+x^3+x^2+1 ─────────
var EXP_TABLE = new Array(256);
var LOG_TABLE = new Array(256);
for(var i=0;i<8;i++) EXP_TABLE[i]=1<<i;
for(var i=8;i<256;i++) EXP_TABLE[i]=EXP_TABLE[i-4]^EXP_TABLE[i-5]^EXP_TABLE[i-6]^EXP_TABLE[i-8];
for(var i=0;i<255;i++) LOG_TABLE[EXP_TABLE[i]]=i;
function glog(n){ if(n<1) throw new Error("glog("+n+")"); return LOG_TABLE[n]; }
function gexp(n){ while(n<0) n+=255; while(n>=256) n-=255; return EXP_TABLE[n]; }

// ── Reed-Solomon polynomial ops ───────────────────────────────────────────────
function Poly(num,shift){
  var off=0; while(off<num.length&&num[off]===0) off++;
  this.num=new Array(num.length-off+shift);
  for(var i=0;i<num.length-off;i++) this.num[i]=num[i+off];
  for(var i=num.length-off;i<this.num.length;i++) this.num[i]=0;
}
Poly.prototype.get=function(i){ return this.num[i]; };
Poly.prototype.getLength=function(){ return this.num.length; };
Poly.prototype.multiply=function(e){
  var num=new Array(this.getLength()+e.getLength()-1);
  for(var i=0;i<num.length;i++) num[i]=0;
  for(var i=0;i<this.getLength();i++)
    for(var j=0;j<e.getLength();j++)
      num[i+j]^=gexp(glog(this.get(i))+glog(e.get(j)));
  return new Poly(num,0);
};
Poly.prototype.mod=function(e){
  if(this.getLength()-e.getLength()<0) return this;
  var ratio=glog(this.get(0))-glog(e.get(0));
  var num=new Array(this.getLength());
  for(var i=0;i<this.getLength();i++) num[i]=this.get(i);
  for(var i=0;i<e.getLength();i++) num[i]^=gexp(glog(e.get(i))+ratio);
  return new Poly(num,0).mod(e);
};
function getErrorCorrectPoly(count){
  var a=new Poly([1],0);
  for(var i=0;i<count;i++) a=a.multiply(new Poly([1,gexp(i)],0));
  return a;
}

// ── RS Block table — ISO 18004:2006 Table 9 ───────────────────────────────────
// Indexed as (version-1)*4 + ecLevel, ecLevel: L=0 M=1 Q=2 H=3
// Each entry: [count, totalCW, dataCW, count2, totalCW2, dataCW2, ...]
// Totals per version (version 1→10): 26,44,70,100,134,172,196,242,292,346
var RS_BLOCK_TABLE = [
  // ── Version 1 (total 26) ──────────────────────────────────────────────────
  [1,26,19],[1,26,16],[1,26,13],[1,26,9],
  // ── Version 2 (total 44) ──────────────────────────────────────────────────
  [1,44,34],[1,44,28],[1,44,22],[1,44,16],
  // ── Version 3 (total 70) ──────────────────────────────────────────────────
  [1,70,55],[1,70,44],[2,35,17],[2,35,13],
  // ── Version 4 (total 100) ─────────────────────────────────────────────────
  [1,100,80],[2,50,32],[2,50,24],[4,25,9],
  // ── Version 5 (total 134) ─────────────────────────────────────────────────
  [1,134,108],[2,67,43],[2,33,15,2,34,16],[2,33,11,2,34,12],
  // ── Version 6 (total 172) ─────────────────────────────────────────────────
  [2,86,68],[4,43,27],[4,43,19],[4,43,15],
  // ── Version 7 (total 196) ─────────────────────────────────────────────────
  [2,98,78],[4,49,31],[2,32,14,4,33,15],[4,39,13,1,40,14],
  // ── Version 8 (total 242) ─────────────────────────────────────────────────
  [2,121,97],[2,60,38,2,61,39],[4,40,18,2,41,19],[4,40,14,2,41,15],
  // ── Version 9 (total 292) ─────────────────────────────────────────────────
  [2,146,116],[3,58,36,2,59,37],[4,36,16,4,37,17],[4,36,12,4,37,13],
  // ── Version 10 (total 346) ────────────────────────────────────────────────
  [2,86,68,2,87,69],[4,69,43,1,70,44],[6,43,19,2,44,20],[6,43,15,2,44,16],
  // ── Version 11 (total 404) ────────────────────────────────────────────────
  [4,101,81],[1,80,50,4,81,51],[4,50,22,2,51,23],[3,36,12,8,37,13],
  // ── Version 12 (total 466) ────────────────────────────────────────────────
  [2,116,92,2,117,93],[6,58,36,2,59,37],[4,46,20,6,47,21],[7,42,14,4,43,15],
  // ── Version 13 (total 532) ────────────────────────────────────────────────
  [4,133,107],[8,59,37,1,60,38],[8,44,20,4,45,21],[12,33,11,4,34,12],
  // ── Version 14 (total 581) ────────────────────────────────────────────────
  [3,145,115,1,146,116],[4,64,40,5,65,41],[11,36,16,5,37,17],[11,36,12,5,37,13],
  // ── Version 15 (total 655) ────────────────────────────────────────────────
  [5,109,87,1,110,88],[5,65,41,5,66,42],[5,54,24,7,55,25],[11,36,12,7,37,13],
  // ── Version 16 (total 733) ────────────────────────────────────────────────
  [5,122,98,1,123,99],[7,73,45,3,74,46],[15,43,19,2,44,20],[3,45,15,13,46,16],
  // ── Version 17 (total 815) ────────────────────────────────────────────────
  [1,135,107,5,136,108],[10,74,46,1,75,47],[1,50,22,15,51,23],[2,42,14,17,43,15],
  // ── Version 18 (total 901) ────────────────────────────────────────────────
  [5,150,120,1,151,121],[9,69,43,4,70,44],[17,50,22,1,51,23],[2,42,14,19,43,15],
  // ── Version 19 (total 991) ────────────────────────────────────────────────
  [3,141,113,4,142,114],[3,70,44,11,71,45],[17,47,21,4,48,22],[9,39,13,16,40,14],
  // ── Version 20 (total 1085) ───────────────────────────────────────────────
  [3,135,107,5,136,108],[3,67,41,13,68,42],[15,54,24,5,55,25],[15,43,15,10,44,16]
];
// Versions 21-40: not needed for Re-fill payloads (max ~120 bytes fits in V10)
for(var _i=0;_i<80;_i++) RS_BLOCK_TABLE.push(null);

function getRSBlocks(typeNumber,ecLevel){
  var idx=(typeNumber-1)*4+ecLevel;
  var entry=RS_BLOCK_TABLE[idx];
  if(!entry) throw new Error("Unsupported QR version "+typeNumber);
  var list=[];
  for(var i=0;i<entry.length;i+=3)
    for(var j=0;j<entry[i];j++) list.push({totalCount:entry[i+1],dataCount:entry[i+2]});
  return list;
}

// ── BitBuffer ─────────────────────────────────────────────────────────────────
function BitBuffer(){ this.buffer=[]; this.length=0; }
BitBuffer.prototype.get=function(i){ return 1===((this.buffer[Math.floor(i/8)]>>>(7-i%8))&1); };
BitBuffer.prototype.put=function(num,length){ for(var i=length-1;i>=0;i--) this.putBit(1===((num>>>i)&1)); };
BitBuffer.prototype.getLengthInBits=function(){ return this.length; };
BitBuffer.prototype.putBit=function(bit){
  var idx=Math.floor(this.length/8);
  if(this.buffer.length<=idx) this.buffer.push(0);
  if(bit) this.buffer[idx]|=0x80>>>(this.length%8);
  this.length++;
};

// ── Byte-mode data segment ────────────────────────────────────────────────────
function QR8bitByte(data){ this.data=data; }
QR8bitByte.prototype.getLength=function(){ return this.data.length; };
QR8bitByte.prototype.write=function(buf){
  for(var i=0;i<this.data.length;i++) buf.put(this.data.charCodeAt(i),8);
};
// Character-count indicator bit-length for byte mode (ISO 18004 Table 3)
function getLengthInBits(ver){ return ver<10?8:16; }

// ── QR geometry ───────────────────────────────────────────────────────────────
// Alignment pattern centre coordinates (ISO 18004 Annex E)
var PATTERN_POS_TABLE=[
  [],
  [6,18],[6,22],[6,26],[6,30],[6,34],
  [6,22,38],[6,24,42],[6,26,46],[6,28,50],[6,30,54],
  [6,32,58],[6,34,62],[6,26,46,66],[6,26,48,70],[6,26,50,74],
  [6,30,54,78],[6,30,56,82],[6,30,58,86],[6,34,62,90]
];
var G15=1335, G18=7973, G15_MASK=21522;
function getBCHDigit(d){ var n=0; while(d!==0){n++;d>>>=1;} return n; }
function getBCHTypeInfo(data){
  var d=data<<10; while(getBCHDigit(d)-getBCHDigit(G15)>=0) d^=G15<<(getBCHDigit(d)-getBCHDigit(G15));
  return ((data<<10)|d)^G15_MASK;
}
function getBCHTypeNumber(data){
  var d=data<<12; while(getBCHDigit(d)-getBCHDigit(G18)>=0) d^=G18<<(getBCHDigit(d)-getBCHDigit(G18));
  return (data<<12)|d;
}
// I map internal ecLevel (L=0 M=1 Q=2 H=3) to QR format-info EC bits (M=00 L=01 H=10 Q=11)
// Without this mapping the scanner reads the wrong correction level from format info
var EC_FORMAT_BITS=[1,0,3,2];

function getMask(pat,i,j){
  switch(pat){
    case 0: return(i+j)%2===0;
    case 1: return i%2===0;
    case 2: return j%3===0;
    case 3: return(i+j)%3===0;
    case 4: return(Math.floor(i/2)+Math.floor(j/3))%2===0;
    case 5: return(i*j)%2+(i*j)%3===0;
    case 6: return((i*j)%2+(i*j)%3)%2===0;
    case 7: return((i*j)%3+(i+j)%2)%2===0;
    default: throw new Error("bad mask "+pat);
  }
}
function getLostPoint(qr){
  var n=qr.getModuleCount(),lp=0,dark,cnt,r,c;
  for(r=0;r<n;r++) for(c=0;c<n;c++){
    cnt=0; dark=qr.isDark(r,c);
    for(var dr=-1;dr<=1;dr++){ if(r+dr<0||n<=r+dr) continue;
      for(var dc=-1;dc<=1;dc++){ if(c+dc<0||n<=c+dc||(!dr&&!dc)) continue;
        if(dark===qr.isDark(r+dr,c+dc)) cnt++;
      }
    }
    if(cnt>5) lp+=(3+cnt-5);
  }
  for(r=0;r<n-1;r++) for(c=0;c<n-1;c++){
    cnt=0;
    if(qr.isDark(r,c)) cnt++; if(qr.isDark(r+1,c)) cnt++;
    if(qr.isDark(r,c+1)) cnt++; if(qr.isDark(r+1,c+1)) cnt++;
    if(cnt===0||cnt===4) lp+=3;
  }
  for(r=0;r<n;r++) for(c=0;c<n-6;c++){
    if(qr.isDark(r,c)&&!qr.isDark(r,c+1)&&qr.isDark(r,c+2)&&qr.isDark(r,c+3)&&
       qr.isDark(r,c+4)&&!qr.isDark(r,c+5)&&qr.isDark(r,c+6)) lp+=40;
  }
  for(c=0;c<n;c++) for(r=0;r<n-6;r++){
    if(qr.isDark(r,c)&&!qr.isDark(r+1,c)&&qr.isDark(r+2,c)&&qr.isDark(r+3,c)&&
       qr.isDark(r+4,c)&&!qr.isDark(r+5,c)&&qr.isDark(r+6,c)) lp+=40;
  }
  var dk=0;
  for(r=0;r<n;r++) for(c=0;c<n;c++) if(qr.isDark(r,c)) dk++;
  lp+=Math.abs(100*dk/n/n-50)/5*10;
  return lp;
}

// ── QR Code model ─────────────────────────────────────────────────────────────
function QRCodeModel(typeNumber,ecLevel){
  this.typeNumber=typeNumber; this.ecLevel=ecLevel;
  this.modules=null; this.moduleCount=0; this.dataCache=null; this.dataList=[];
}
QRCodeModel.prototype.addData=function(s){ this.dataList.push(new QR8bitByte(s)); this.dataCache=null; };
QRCodeModel.prototype.isDark=function(r,c){
  if(r<0||this.moduleCount<=r||c<0||this.moduleCount<=c) throw new Error(r+","+c);
  return this.modules[r][c];
};
QRCodeModel.prototype.getModuleCount=function(){ return this.moduleCount; };
QRCodeModel.prototype.make=function(){
  if(this.typeNumber<1){
    // I find the minimum version that fits the data at the chosen EC level
    for(var t=1;t<=20;t++){
      var rsBlocks=getRSBlocks(t,this.ecLevel);
      var buf=new BitBuffer();
      buf.put(4,4); // byte-mode indicator
      buf.put(this.dataList[0].getLength(),getLengthInBits(t));
      this.dataList[0].write(buf);
      var cap=0; for(var i=0;i<rsBlocks.length;i++) cap+=rsBlocks[i].dataCount;
      if(buf.getLengthInBits()<=cap*8){ this.typeNumber=t; break; }
    }
    if(this.typeNumber<1) throw new Error("Data too long for version 20");
  }
  this.makeImpl(false,this.getBestMaskPattern());
};
QRCodeModel.prototype.makeImpl=function(test,maskPattern){
  this.moduleCount=4*this.typeNumber+17;
  this.modules=[];
  for(var r=0;r<this.moduleCount;r++){ this.modules[r]=[];
    for(var c=0;c<this.moduleCount;c++) this.modules[r][c]=null;
  }
  this.setupPositionProbePattern(0,0);
  this.setupPositionProbePattern(this.moduleCount-7,0);
  this.setupPositionProbePattern(0,this.moduleCount-7);
  this.setupPositionAdjustPattern();
  this.setupTimingPattern();
  this.setupTypeInfo(test,maskPattern);
  if(this.typeNumber>=7) this.setupTypeNumber(test);
  if(!this.dataCache) this.dataCache=QRCodeModel.createData(this.typeNumber,this.ecLevel,this.dataList);
  this.mapData(this.dataCache,maskPattern);
};
QRCodeModel.prototype.setupPositionProbePattern=function(row,col){
  for(var r=-1;r<=7;r++){ if(row+r<=-1||this.moduleCount<=row+r) continue;
    for(var c=-1;c<=7;c++){ if(col+c<=-1||this.moduleCount<=col+c) continue;
      this.modules[row+r][col+c]=
        (r>=0&&r<=6&&(c===0||c===6))||
        (c>=0&&c<=6&&(r===0||r===6))||
        (r>=2&&r<=4&&c>=2&&c<=4);
    }
  }
};
QRCodeModel.prototype.getBestMaskPattern=function(){
  var min=0,pat=0;
  for(var i=0;i<8;i++){ this.makeImpl(true,i); var lp=getLostPoint(this);
    if(i===0||min>lp){ min=lp; pat=i; }
  }
  return pat;
};
QRCodeModel.prototype.setupTimingPattern=function(){
  for(var r=8;r<this.moduleCount-8;r++) if(this.modules[r][6]===null) this.modules[r][6]=(r%2===0);
  for(var c=8;c<this.moduleCount-8;c++) if(this.modules[6][c]===null) this.modules[6][c]=(c%2===0);
};
QRCodeModel.prototype.setupPositionAdjustPattern=function(){
  var pos=PATTERN_POS_TABLE[this.typeNumber-1];
  for(var i=0;i<pos.length;i++) for(var j=0;j<pos.length;j++){
    var row=pos[i],col=pos[j];
    if(this.modules[row][col]!==null) continue;
    for(var r=-2;r<=2;r++) for(var c=-2;c<=2;c++)
      this.modules[row+r][col+c]=(r===-2||r===2||c===-2||c===2||(r===0&&c===0));
  }
};
QRCodeModel.prototype.setupTypeNumber=function(test){
  var bits=getBCHTypeNumber(this.typeNumber);
  for(var i=0;i<18;i++){
    var mod=(!test)&&((bits>>i)&1)===1;
    this.modules[Math.floor(i/3)][i%3+this.moduleCount-8-3]=mod;
  }
  for(var i=0;i<18;i++){
    var mod=(!test)&&((bits>>i)&1)===1;
    this.modules[i%3+this.moduleCount-8-3][Math.floor(i/3)]=mod;
  }
};
QRCodeModel.prototype.setupTypeInfo=function(test,maskPattern){
  var data=(EC_FORMAT_BITS[this.ecLevel]<<3)|maskPattern;
  var bits=getBCHTypeInfo(data);
  // Horizontal copy
  for(var i=0;i<15;i++){
    var mod=(!test)&&((bits>>i)&1)===1;
    if(i<6) this.modules[i][8]=mod;
    else if(i<8) this.modules[i+1][8]=mod;
    else this.modules[this.moduleCount-15+i][8]=mod;
  }
  // Vertical copy
  for(var i=0;i<15;i++){
    var mod=(!test)&&((bits>>i)&1)===1;
    if(i<8) this.modules[8][this.moduleCount-i-1]=mod;
    else if(i<9) this.modules[8][15-i]=mod;
    else this.modules[8][15-i-1]=mod;
  }
  // Dark module — always set at (moduleCount-8, 8)
  this.modules[this.moduleCount-8][8]=!test;
};
QRCodeModel.prototype.mapData=function(data,maskPattern){
  var inc=-1,row=this.moduleCount-1,bitIndex=7,byteIndex=0;
  for(var col=this.moduleCount-1;col>0;col-=2){
    if(col===6) col--;
    for(;;){
      for(var c=0;c<2;c++){
        if(this.modules[row][col-c]===null){
          var dark=false;
          if(byteIndex<data.length) dark=((data[byteIndex]>>>bitIndex)&1)===1;
          if(getMask(maskPattern,row,col-c)) dark=!dark;
          this.modules[row][col-c]=dark;
          if(--bitIndex===-1){ byteIndex++; bitIndex=7; }
        }
      }
      row+=inc;
      if(row<0||this.moduleCount<=row){ row-=inc; inc=-inc; break; }
    }
  }
};
QRCodeModel.createData=function(typeNumber,ecLevel,dataList){
  var rsBlocks=getRSBlocks(typeNumber,ecLevel), buf=new BitBuffer();
  for(var i=0;i<dataList.length;i++){
    buf.put(4,4);
    buf.put(dataList[i].getLength(),getLengthInBits(typeNumber));
    dataList[i].write(buf);
  }
  var cap=0; for(var i=0;i<rsBlocks.length;i++) cap+=rsBlocks[i].dataCount;
  if(buf.getLengthInBits()>cap*8) throw new Error("Data overflow");
  if(buf.getLengthInBits()+4<=cap*8) buf.put(0,4);
  while(buf.getLengthInBits()%8!==0) buf.putBit(false);
  while(buf.getLengthInBits()<cap*8){
    buf.put(0xEC,8);
    if(buf.getLengthInBits()>=cap*8) break;
    buf.put(0x11,8);
  }
  return QRCodeModel.createBytes(buf,rsBlocks);
};
QRCodeModel.createBytes=function(buf,rsBlocks){
  var off=0,maxDC=0,maxEC=0;
  var dc=new Array(rsBlocks.length), ec=new Array(rsBlocks.length);
  for(var r=0;r<rsBlocks.length;r++){
    var dcCount=rsBlocks[r].dataCount, ecCount=rsBlocks[r].totalCount-dcCount;
    maxDC=Math.max(maxDC,dcCount); maxEC=Math.max(maxEC,ecCount);
    dc[r]=new Array(dcCount);
    for(var i=0;i<dcCount;i++) dc[r][i]=0xff&buf.buffer[i+off];
    off+=dcCount;
    var rsPoly=getErrorCorrectPoly(ecCount), rawPoly=new Poly(dc[r],ecCount);
    var modPoly=rawPoly.mod(rsPoly);
    ec[r]=new Array(ecCount);
    for(var i=0;i<ecCount;i++){
      var mi=i+modPoly.getLength()-ecCount;
      ec[r][i]=(mi>=0)?modPoly.get(mi):0;
    }
  }
  var total=0; for(var i=0;i<rsBlocks.length;i++) total+=rsBlocks[i].totalCount;
  var data=new Array(total), idx=0;
  for(var i=0;i<maxDC;i++) for(var r=0;r<rsBlocks.length;r++) if(i<dc[r].length) data[idx++]=dc[r][i];
  for(var i=0;i<maxEC;i++) for(var r=0;r<rsBlocks.length;r++) if(i<ec[r].length) data[idx++]=ec[r][i];
  return data;
};

// ── Canvas renderer ───────────────────────────────────────────────────────────
// I add a 4-module quiet zone on all sides — the QR spec requires this so
// scanners can locate the finder patterns
function drawQR(el,qr,opts){
  var n=qr.getModuleCount(), quiet=4, total=n+quiet*2;
  var tile=Math.floor(Math.min(opts.width,opts.height)/total);
  if(tile<1) tile=1;
  var sz=tile*total;
  var canvas=document.createElement('canvas');
  canvas.width=sz; canvas.height=sz;
  var ctx=canvas.getContext('2d');
  ctx.fillStyle=opts.colorLight; ctx.fillRect(0,0,sz,sz);
  ctx.fillStyle=opts.colorDark;
  for(var row=0;row<n;row++) for(var col=0;col<n;col++){
    if(qr.isDark(row,col)) ctx.fillRect((col+quiet)*tile,(row+quiet)*tile,tile,tile);
  }
  try{
    // Render as an <img> so the browser can scale it cleanly
    var img=document.createElement('img');
    img.src=canvas.toDataURL('image/png');
    img.style.width=opts.width+'px'; img.style.height=opts.height+'px';
    img.style.display='block'; img.style.imageRendering='pixelated';
    el.appendChild(img);
  }catch(e){
    canvas.style.width=opts.width+'px'; canvas.style.height=opts.height+'px';
    el.appendChild(canvas);
  }
}
function drawTable(el,qr,opts){
  var n=qr.getModuleCount();
  var tw=Math.floor(opts.width/n), th=Math.floor(opts.height/n);
  var tbl=document.createElement('table');
  tbl.style.cssText='border-collapse:collapse;width:'+opts.width+'px;height:'+opts.height+'px;';
  for(var r=0;r<n;r++){
    var tr=tbl.insertRow(-1); tr.style.height=th+'px';
    for(var c=0;c<n;c++){
      var td=tr.insertCell(-1); td.style.width=tw+'px';
      td.style.backgroundColor=qr.isDark(r,c)?opts.colorDark:opts.colorLight;
    }
  }
  el.appendChild(tbl);
}

// ── Public API ────────────────────────────────────────────────────────────────
// I keep the same constructor signature as the original davidshimjs/qrcodejs
// so existing code using new QRCode(el, options) keeps working unchanged
function QRCode(el,options){
  if(typeof options==='string') options={text:options};
  var defs={width:256,height:256,typeNumber:-1,colorDark:'#000000',colorLight:'#ffffff',correctLevel:1};
  for(var k in defs) if(!(k in options)) options[k]=defs[k];
  if(typeof el==='string') el=document.getElementById(el);
  var qr=new QRCodeModel(-1,options.correctLevel);
  qr.addData(options.text);
  qr.make();
  if(typeof CanvasRenderingContext2D!=='undefined') drawQR(el,qr,options);
  else drawTable(el,qr,options);
}
// CorrectLevel constants — L=0 M=1 Q=2 H=3 match RS_BLOCK_TABLE column offsets
QRCode.CorrectLevel={L:0,M:1,Q:2,H:3};

if(typeof define==='function'&&define.amd) define([],function(){ return QRCode; });
else if(typeof module==='object'&&module.exports) module.exports=QRCode;
else window.QRCode=QRCode;

})();
